export function findWorldLeader(query: string): string | null {
  const q = query.toLowerCase();
  
  // Sort keys by length descending to match multi-word countries first (e.g. "South Africa" before "Africa")
  const keys = Object.keys(WORLD_LEADERS).sort((a, b) => b.length - a.length);

  for (const key of keys) {
    const regex = new RegExp(`\\b${key}\\b`, 'i');
    if (regex.test(q)) {
      const entry = WORLD_LEADERS[key];
      return `VERIFIED CURRENT OFFICEHOLDERS (${entry.country.toUpperCase()}): ${entry.leaders}`;
    }
  }

  return null;
}
